using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
namespace ReplyAI.Updates {
 public sealed class PackageFile {public string Path {get;set;} public string Sha256 {get;set;}}
 public sealed class PackageManifest {public string Product {get;set;} public string Version {get;set;} public List<PackageFile> Files {get;set;}}
 public sealed class UpdateJob {public string InstallRoot {get;set;} public string StageRoot {get;set;} public int ProcessId {get;set;} public long ProcessStartTicks {get;set;} public string Version {get;set;}}
 public static class UpdatePackage {
  public const string Repository="abdelrazak27/ReplyAI";
  public const string AssetName="ReplyAI-win-x64.zip";
  public const long MaxArchiveBytes=268435456,MaxExtractedBytes=805306368;
  public static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=2097152,RecursionLimit=32};}
  public static Version ParseVersion(string text){Version value;string input=(text??"").TrimStart('v','V');if(!Regex.IsMatch(input,@"^\d+\.\d+\.\d+(?:\.\d+)?$")||!Version.TryParse(input,out value))throw new InvalidDataException("Version de publication invalide.");return new Version(value.Major,value.Minor,value.Build,Math.Max(0,value.Revision));}
  public static string Hash(string path){using(var stream=File.OpenRead(path))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
  public static bool ValidHash(string hash){return Regex.IsMatch(hash??"",@"^[a-fA-F0-9]{64}$");}
  public static string Relative(string path){string rel=(path??"").Replace('\\','/');if(String.IsNullOrEmpty(rel)||rel.Length>220||rel.StartsWith("/")||rel.Contains(":")||rel.Any(Char.IsControl))throw new InvalidDataException("Chemin de mise à jour invalide.");foreach(string part in rel.Split('/')){if(part==""||part=="."||part==".."||part.EndsWith(".")||part.EndsWith(" ")||part.IndexOfAny(new[]{'*','?','"','<','>','|'})>=0||Regex.IsMatch(part,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)",RegexOptions.IgnoreCase))throw new InvalidDataException("Chemin de mise à jour interdit.");}
   bool allowed=rel=="ReplyAI.exe"||rel=="LANCER.cmd"||rel=="LISEZ-MOI.md"||rel=="update-manifest.json"||rel.StartsWith("brand/",StringComparison.Ordinal)||Regex.IsMatch(rel,@"^engine-[A-Za-z0-9._-]+/");if(!allowed)throw new InvalidDataException("Fichier hors du périmètre de l’application.");return rel;}
  public static string Destination(string root,string relative){string fullRoot=System.IO.Path.GetFullPath(root).TrimEnd('\\','/');string result=System.IO.Path.GetFullPath(System.IO.Path.Combine(fullRoot,Relative(relative).Replace('/',System.IO.Path.DirectorySeparatorChar)));if(!result.StartsWith(fullRoot+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Chemin en dehors du dossier de l’application.");return result;}
  public static void NoLinks(string root,string relative){string cursor=System.IO.Path.GetFullPath(root);if(Directory.Exists(cursor)&&(File.GetAttributes(cursor)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Le dossier de mise à jour est un lien.");foreach(string part in Relative(relative).Split('/')){cursor=System.IO.Path.Combine(cursor,part);if((Directory.Exists(cursor)||File.Exists(cursor))&&(File.GetAttributes(cursor)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Un lien a été trouvé dans les fichiers de mise à jour.");}}
  public static PackageManifest Verify(string root,string expected){string manifestPath=System.IO.Path.Combine(root,"update-manifest.json");if(!File.Exists(manifestPath)||new FileInfo(manifestPath).Length>1048576)throw new InvalidDataException("Manifest de mise à jour absent ou trop volumineux.");var manifest=Json().Deserialize<PackageManifest>(File.ReadAllText(manifestPath));if(manifest==null||manifest.Product!="Reply AI"||ParseVersion(manifest.Version)!=ParseVersion(expected)||manifest.Files==null||manifest.Files.Count<2||manifest.Files.Count>2000)throw new InvalidDataException("Manifest de mise à jour invalide.");var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long total=0;foreach(var file in manifest.Files){string rel=Relative(file.Path);if(rel=="update-manifest.json"||!names.Add(rel)||!ValidHash(file.Sha256))throw new InvalidDataException("Liste de fichiers invalide.");NoLinks(root,rel);string path=Destination(root,rel);if(!File.Exists(path)||!String.Equals(Hash(path),file.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("L’intégrité des fichiers de mise à jour n’est pas vérifiée.");total+=new FileInfo(path).Length;if(total>MaxExtractedBytes)throw new InvalidDataException("Mise à jour trop volumineuse.");}if(!names.Contains("ReplyAI.exe")||!names.Any(n=>Regex.IsMatch(n,@"^engine-[^/]+/parole-engine\.exe$")))throw new InvalidDataException("Application ou moteur manquant.");var disk=Directory.GetFiles(root,"*",SearchOption.AllDirectories).Select(p=>p.Substring(System.IO.Path.GetFullPath(root).TrimEnd('\\','/').Length+1).Replace('\\','/')).ToList();if(disk.Any(n=>n!="update-manifest.json"&&!names.Contains(n)))throw new InvalidDataException("Fichiers inattendus dans la mise à jour.");return manifest;}
  public static PackageManifest Extract(string zipPath,string root,string expected,string sha256){if(!ValidHash(sha256)||!String.Equals(Hash(zipPath),sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Le téléchargement est incomplet ou sa somme de contrôle est incorrecte.");if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new InvalidDataException("Le dossier temporaire n’est pas vide.");Directory.CreateDirectory(root);using(var zip=ZipFile.OpenRead(zipPath)){if(zip.Entries.Count>2200)throw new InvalidDataException("Trop de fichiers dans la mise à jour.");long total=0;var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var entry in zip.Entries){string name=entry.FullName.Replace('\\','/');if(!name.StartsWith("ReplyAI/",StringComparison.Ordinal))throw new InvalidDataException("Structure du paquet incorrecte.");if(((entry.ExternalAttributes>>16)&0xF000)==0xA000)throw new InvalidDataException("Liens symboliques interdits.");if(name.EndsWith("/")){if(name!="ReplyAI/")Relative(name.Substring(8).TrimEnd('/'));continue;}string rel=Relative(name.Substring(8));if(!paths.Add(rel))throw new InvalidDataException("Fichier en double dans la mise à jour.");total+=entry.Length;if(entry.Length>MaxExtractedBytes||total>MaxExtractedBytes)throw new InvalidDataException("Paquet décompressé trop volumineux.");string destination=Destination(root,rel);Directory.CreateDirectory(System.IO.Path.GetDirectoryName(destination));using(var source=entry.Open())using(var target=new FileStream(destination,FileMode.CreateNew,FileAccess.Write)){byte[] buffer=new byte[81920];long written=0;int read;while((read=source.Read(buffer,0,buffer.Length))>0){written+=read;if(written>entry.Length)throw new InvalidDataException("Taille de fichier incorrecte.");target.Write(buffer,0,read);}}}}return Verify(root,expected);}
  public static void Install(string stage,string install,string backup,string expected,Action<string,string> copy=null){var manifest=Verify(stage,expected);string targetRoot=System.IO.Path.GetFullPath(install).TrimEnd('\\','/'),stageRoot=System.IO.Path.GetFullPath(stage).TrimEnd('\\','/'),backupRoot=System.IO.Path.GetFullPath(backup).TrimEnd('\\','/');if(targetRoot==stageRoot||backupRoot==targetRoot||backupRoot.StartsWith(targetRoot+"\\",StringComparison.OrdinalIgnoreCase)||stageRoot.StartsWith(targetRoot+"\\",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Dossiers de mise à jour incompatibles.");if(!File.Exists(System.IO.Path.Combine(targetRoot,"ReplyAI.exe")))throw new InvalidDataException("Installation Reply AI introuvable.");if(Directory.Exists(backupRoot)&&Directory.EnumerateFileSystemEntries(backupRoot).Any())throw new InvalidDataException("Sauvegarde temporaire déjà occupée.");Directory.CreateDirectory(backupRoot);var files=manifest.Files.Select(f=>f.Path).Concat(new[]{"update-manifest.json"}).ToList();var originals=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string rel in files){NoLinks(targetRoot,rel);string target=Destination(targetRoot,rel);if(File.Exists(target)){string saved=Destination(backupRoot,rel);Directory.CreateDirectory(System.IO.Path.GetDirectoryName(saved));File.Copy(target,saved,false);originals.Add(rel);}}
   var written=new List<string>();try{foreach(string rel in files){string target=Destination(targetRoot,rel);Directory.CreateDirectory(System.IO.Path.GetDirectoryName(target));written.Add(rel);if(copy==null)File.Copy(Destination(stageRoot,rel),target,true);else copy(Destination(stageRoot,rel),target);}}
   catch(Exception failure){var failures=new List<Exception>();foreach(string rel in written.AsEnumerable().Reverse()){try{string target=Destination(targetRoot,rel);if(originals.Contains(rel))File.Copy(Destination(backupRoot,rel),target,true);else if(File.Exists(target))File.Delete(target);}catch(Exception error){failures.Add(error);}}if(failures.Count>0)throw new IOException("La restauration n’a pas pu se terminer. Copie précédente : "+backupRoot,new AggregateException(failures));throw new IOException("La mise à jour a échoué ; la version précédente a été restaurée.",failure);}
  }
 }
}
